#include <bits/stdc++.h>
using namespace std;

using ll = long long;

bool isPalindrome(ll n) {
    ll original = n;
    ll reversed = 0;

    while (n > 0) {
        reversed = reversed * 10 + n % 10;
        n /= 10;
    }

    return original == reversed;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long double p, q;
    cin >> p >> q;

    constexpr int LIMIT = 10000004;
    vector<bool> composite(LIMIT + 1, false);

    ll primeCount = 0;
    ll palindromeCount = 0;
    int answer = -1;

    for (ll i = 1; i <= LIMIT; ++i) {
        if (i >= 2 && !composite[i]) {
            ++primeCount;

            if (i * i <= LIMIT) {
                for (ll j = i * i; j <= LIMIT; j += i) {
                    composite[j] = true;
                }
            }
        }

        if (isPalindrome(i)) {
            ++palindromeCount;
        }

        if (primeCount * q <= palindromeCount * p) {
            answer = static_cast<int>(i);
        }
    }

    if (answer != -1) {
        cout << answer << '\n';
    } else {
        cout << "Palindromic tree is better than splay tree\n";
    }

    return 0;
}

