#include <bits/stdc++.h>
using namespace std;

long long makePalindrome(int seed, bool oddLength) {
    long long result = seed;
    int remaining = oddLength ? seed / 10 : seed;

    while (remaining > 0) {
        result = result * 10 + remaining % 10;
        remaining /= 10;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    constexpr int LIMIT = 10000004;

    double p, q;
    cin >> p >> q;

    vector<bool> composite(LIMIT + 1, false);
    for (int i = 2; 1LL * i * i <= LIMIT; ++i) {
        if (!composite[i]) {
            for (long long j = 1LL * i * i; j <= LIMIT; j += i) {
                composite[static_cast<int>(j)] = true;
            }
        }
    }

    vector<int> palindromes;
    for (bool oddLength : {true, false}) {
        for (int seed = 1;; ++seed) {
            long long palindrome = makePalindrome(seed, oddLength);
            if (palindrome > LIMIT) {
                break;
            }
            palindromes.push_back(static_cast<int>(palindrome));
        }
    }

    sort(palindromes.begin(), palindromes.end());
    palindromes.erase(unique(palindromes.begin(), palindromes.end()),
                      palindromes.end());

    long long primeCount = 0;
    long long palindromeCount = 0;
    int answer = -1;
    size_t palindromeIndex = 0;

    for (int i = 1; i <= LIMIT; ++i) {
        if (i >= 2 && !composite[i]) {
            ++primeCount;
        }

        while (palindromeIndex < palindromes.size() &&
               palindromes[palindromeIndex] == i) {
            ++palindromeCount;
            ++palindromeIndex;
        }

        if (primeCount * q <= palindromeCount * p) {
            answer = i;
        }
    }

    if (answer != -1) {
        cout << answer << '\n';
    } else {
        cout << "Palindromic tree is better than splay tree\n";
    }

    return 0;
}

